    return a if a < b else b

def max_ll(a, b):
    return a if a > b else b

def lucky(i):
    return 0 if i == 1 else lucky(i // 2) * 10 + (4 if i % 2 == 0 else 7)

def main():
    aa = [0] * 2047
    l, r = map(int, input().split())
    aa[0] = 4
    for i in range(1, 2047):
        aa[i] = lucky(i + 1)
